@graph.description:
task spearman_correlation {
    Array[File] quants
    String output_filename

    command {
        python3 $(which calculate_correlation.py) --quants ${sep=' ' quants} --output_filename ${output_filename}
    }

    output {
        File spearman_json = glob("*spearman.json")[0]
    }

    runtime {
        cpu: 1
        memory: "2 GB"
        disks: "local-disk 20 SSD"
    }
}
